test("artboard はその幅を答える", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "home", "width"),
  ).toEqual(Option.some(360));
});

test("artboard はその高さを答える", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "home", "height"),
  ).toEqual(Option.some(240));
});

test("大きさのモードを書いていない Ellipse は、書かれた幅を答える", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "oval", "width"),
  ).toEqual(Option.some(140));
});

test("大きさのモードを書いていない Ellipse は、書かれた高さを答える", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "oval", "height"),
  ).toEqual(Option.some(72));
});

test("長さもモードも書いていない Ellipse は、既定の長さを答える", () => {
  expect(DesignDocument.fixedLengthOf(setupDocument(), "dot", "width")).toEqual(
    Option.some(100),
  );
});

test("長さだけを書いた Box は、既定のモードが hug なので答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "plain", "width"),
  ).toEqual(Option.none);
});

test("モードを fixed にしただけの Box は、長さも既定も無いので答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "unsized", "width"),
  ).toEqual(Option.none);
});

test("fill を明示した Ellipse の軸は、長さが書いてあっても答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "stretched", "width"),
  ).toEqual(Option.none);
});

test("部品インスタンスは長さを答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "instance", "width"),
  ).toEqual(Option.none);
});

test("スキーマに無い type のノードは、fixed と長さを書いていても答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "unknown", "width"),
  ).toEqual(Option.none);
});

test("スキーマに無い大きさの prop を書いた Text は、fixed と長さを書いていても答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "label", "width"),
  ).toEqual(Option.none);
});

test("ドキュメントに無い名前は長さを答えない", () => {
  expect(
    DesignDocument.fixedLengthOf(setupDocument(), "missing", "width"),
  ).toEqual(Option.none);
});

test("モードを書いていない Ellipse は、書かれた長さで幅と高さの両方のハンドルが出る", () => {
  expect(NodeResize.resizable(setupSelection(["oval"])).lengths).toEqual([
    { axis: "width", length: 140 },
    { axis: "height", length: 72 },
  ]);
});

test("何も書いていない Ellipse は、既定の長さで幅と高さの両方のハンドルが出る", () => {
  expect(NodeResize.resizable(setupSelection(["dot"])).lengths).toEqual([
    { axis: "width", length: 100 },
    { axis: "height", length: 100 },
  ]);
});

test("高さを fill にした Ellipse は幅のハンドルだけが出る", () => {
  expect(handlesOf("bar")).toEqual(["width"]);
});

test("モードを書かずに長さだけを書いた Box は、既定が hug なのでハンドルが出ない", () => {
  expect(handlesOf("plain")).toEqual([]);
});

test("スキーマに無い widthMode を書いた Text はハンドルが出ない", () => {
  expect(handlesOf("caption")).toEqual([]);
});

test("スキーマに無い type のノードはハンドルが出ない", () => {
  expect(handlesOf("mystery")).toEqual([]);
});

test("大きさのモードを持たない Text はハンドルが出ない", () => {
  expect(handlesOf("title")).toEqual([]);
});

test("部品インスタンスにはハンドルが出ない", () => {
  expect(handlesOf("action")).toEqual([]);
});

test("artboard は常に幅と高さの両方のハンドルが出る", () => {
  expect(handlesOf("home")).toEqual(["width", "height"]);
});

test("fixed でも長さが決まっていない軸のハンドルは出ない", () => {
  expect(handlesOf("broken")).toEqual([]);
});

test("モードを書いていない Ellipse を選ぶとハンドルが描かれる", () => {
  renderCanvas({ selection: setupSelection(["oval"]) });

  expect(resizeHandles()).toHaveLength(8);
});

test("大きさのモードを持たない Text を選んでもハンドルは描かれない", () => {
  renderCanvas({ selection: setupSelection(["title"]) });

  expect(resizeHandles()).toHaveLength(0);
});

test("モードを書いていない Ellipse の右辺を運ぶと、描かれる幅が動かした分だけ広がる", async () => {
  await renderOpenedDocument(setupDocument());
  await selectInTree("ring");

  dragRightEdge("ring");

  expect(drawn("ring").style.width).toBe("240px");
});

/**
 * 名前で指した artboard / ノードが、`fixed` の軸に今持っている長さ。artboard は 2 軸とも
 * `fixed` 固定なので常に答える（docs/03-schema.md）。
 *
 * @param document 引き先になるドキュメント
 * @param name 長さを知りたい artboard / ノードの名前
 * @param axis どちらの軸の長さか
 * @returns その軸の長さ。名前が無い / 部品インスタンス / スキーマに無い type /
 *   `hug` `fill` / `fixed` なのに長さも既定も無いときは `none`
 */
fixedLengthOf(
  document: DesignDocument,
  name: string,
  axis: Axis,
): Option<number> {
  const artboard = DesignDocument.findArtboard(document, name);
  if (Option.isSome(artboard)) {
    return Option.some(artboard.value[axis]);
  }
  const node = DesignDocument.findNode(document, name);
  if (!Option.isSome(node) || !Node.isPrimitive(node.value)) {
    return Option.none;
  }
  return Option.flatMap(ResolvedProps.forNode(node.value), (props) =>
    Size.fixedLengthFromProps(props, axis),
  );
},
